 t=s.get('type')
 tests={'object':lambda:isinstance(x,dict),'array':lambda:isinstance(x,list),'string':lambda:isinstance(x,str),'boolean':lambda:type(x) is bool,'number':lambda:type(x) in (int,float),'integer':lambda:type(x) is int}
 if t: assert tests[t](),(path,'type',t)
