asts=[];hashes={}; diagnostic_count=0
for v in p['variants']:
 f=Path(v['file']);assert f.name==str(f) and f.suffix=='.py'
 s=f.read_text();compile(s,str(f),'exec');tree=ast.parse(s)
 cfg_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 cfg=ast.literal_eval(cfg_node.value);assert cfg==v['config'] and cfg['compact_mode']=='histogram'
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 assert len(methods)==sum(isinstance(n,ast.FunctionDef) for n in cls.body),'duplicate methods'
 for name,old in base_methods.items():
  nn={'forward':'_histogram_forward','diagnostics':'_histogram_diagnostics'}.get(name,name)
  new=copy.deepcopy(methods[nn]);new.name=name
  if name=='__init__':
   new.body=new.body[:len(old.body)]
  assert ast.dump(new)==ast.dump(old),(v['name'],'parent drift',name)
 # Prove readout and selection formulas match the inherited implementation.
 for oldname,newname in [('_compact_readout','_fusion_readout'),('_compact_select','_fusion_select')]:
  old=copy.deepcopy(base_methods[oldname]);old.name=newname
  for node in ast.walk(old):
   if isinstance(node,ast.Attribute) and node.attr.startswith('compact_'): node.attr='fusion_'+node.attr[len('compact_'):]
  assert ast.dump(old)==ast.dump(methods[newname]),(v['name'],'readout drift')
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name in ['math','torch'] for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module=='torch'
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in ['open','eval','exec','compile','__import__','getattr']
 assert not ({'make_optimizer','training_loss'} & set(methods))
 cfg_node.value=ast.Constant(value=None)
 asts.append(ast.dump(tree));hashes[str(f)]=hashlib.sha256(s.encode()).hexdigest()
assert len(set(asts))==1,'variant implementations differ'
# Enumerate result keys in inherited44 plus new18 diagnostics, accounting for
# fixed loops/default lists. This is an AST bound; host confirms actual output.
def result_keys(fn):
 keys=set()
 for n in ast.walk(fn):
  if isinstance(n,ast.Assign):
   for target in n.targets:
    if isinstance(target,ast.Name) and target.id=='result' and isinstance(n.value,ast.Dict): keys.update(k.value for k in n.value.keys if isinstance(k,ast.Constant))
    if isinstance(target,ast.Subscript) and isinstance(target.value,ast.Name) and target.value.id=='result' and isinstance(target.slice,ast.Constant): keys.add(target.slice.value)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='result' and n.func.attr=='update' and isinstance(n.args[0],ast.Dict): keys.update(k.value for k in n.args[0].keys if isinstance(k,ast.Constant))
 # Both functions initialize dynamic result[name] exclusively from fixed string
 # lists or tuples; witness_defaults belongs only to inherited diagnostics.
 for n in ast.walk(fn):
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='witness_defaults' for t in n.targets): keys.update(ast.literal_eval(n.value))
  if isinstance(n,ast.For) and isinstance(n.target,ast.Name) and n.target.id=='name' and isinstance(n.iter,(ast.Tuple,ast.List)): keys.update(ast.literal_eval(n.iter))
 return keys
old_keys=result_keys(methods['_histogram_diagnostics']);new_keys=result_keys(methods['diagnostics'])
assert not old_keys.intersection(new_keys)
assert len(old_keys|new_keys)<=64
expected_add=32*32+32+68*32+16*32+16*32
assert expected_add==4256
assert 17191827+expected_add==17196083
assert 113139+expected_add==117395
assert 16*r['context']['protocol']['trial_cap_seconds']<r['context']['remaining_seconds']
