p['validation_plan']['local_results']={'syntax':'4/4 pass via in-memory compile; no imports/execution','schema':'Recursive resolved study-schema validation passed; allowed observation/protocol/parent IDs verified','lineage':'All inherited constructor statements remain an exact AST prefix; every inherited method body is exact with public forward/diagnostics renamed only','matching':'Model AST identical across all four variants; only literal CONFIG differs. Second readout and selection AST exactly equal inherited formulas after compact_ to fusion_ attribute substitution. Same parameter allocation and initialization in every variant.','parameters_expected':{'total':17196083,'embedding':17078688,'dense':117395,'added_vs_histogram_parent':4256,'added_vs_exchangeable':8512},'diagnostic_scalars_upper_bound':len(old_keys|new_keys),'diagnostic_breakdown':{'inherited':len(old_keys),'new':len(new_keys)},'imports':'math and torch only; no file/network access or optimizer/loss override','module_sha256':hashes,'not_verified':['Torch/CUDA execution','finite[B] logits or gradients for these new modules','host training or predictive results','measured cost for new modules','paired-seed reproducibility']}
