for v in p['variants']:
 v['note']+=' Local syntax/source/schema checks passed; identical implementation across variants except CONFIG. '+f\"Module SHA256={hashes[v['file']]}. \"
 v['note']+='Expected17196083 total/117395 dense parameters; added4256 versus retained histogram parent. Training, logits, gradients and measured cost pending on host; inherited function/constructor AST preserved. Model/selection/readout source checks do not establish predictive benefit.'
Path('proposal.json').write_text(json.dumps(p,indent=2)+'\\n')
print(json.dumps({'checks':'passed','inherited_method_count':len(base_methods),'diagnostics':len(old_keys|new_keys),'expected_added_parameters':expected_add,'module_sha256':hashes},indent=2))
